pm.test("Login returns HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Login returns valid token", function () {
    const body = pm.response.json();

    pm.expect(body.success).to.eql(true);
    pm.expect(body.data.token).to.be.a("string").and.not.empty;
    pm.collectionVariables.set("authToken", body.data.token);
});

pm.test("Profile returns HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Profile contains correct user data", function () {
    const body = pm.response.json();

    pm.expect(body.success).to.eql(true);

    pm.expect(body.data.id).to.be.a("string").and.not.empty;
    pm.expect(body.data.name).to.be.a("string").and.not.empty;

    pm.expect(body.data.email).to.eql(
        pm.environment.get("email")
    );
});

pm.test("Create Note returns HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Created Note matches request data", function () {
    const body = pm.response.json();

    pm.expect(body.success).to.eql(true);
    pm.expect(body.data.id).to.be.a("string").and.not.empty;
    pm.expect(body.data.title).to.eql(
        pm.collectionVariables.get("noteTitle")
    );
    pm.expect(body.data.completed).to.eql(false);
});

if (pm.response.code === 200) {
    const body = pm.response.json();

    if (body.success && typeof body.data?.id === "string" && body.data.id.length > 0) {
        pm.collectionVariables.set("noteId", body.data.id);
    }
}

pm.test("Get Note returns HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Persisted Note matches created data", function () {
    const body = pm.response.json();

    pm.expect(body.success).to.eql(true);
    pm.expect(body.data.id).to.eql(
        pm.collectionVariables.get("noteId")
    );
    pm.expect(body.data.title).to.eql(
        pm.collectionVariables.get("noteTitle")
    );
    pm.expect(body.data.description).to.eql(
        "Created by Postman automation"
    );
    pm.expect(body.data.category).to.eql("Work");
    pm.expect(body.data.completed).to.eql(false);
});

pm.test("Update Note returns HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Updated Note contains expected data", function () {
    const body = pm.response.json();

    pm.expect(body.success).to.eql(true);

    pm.expect(body.data.id).to.eql(
        pm.collectionVariables.get("noteId")
    );

    pm.expect(body.data.title).to.eql(
        `${pm.collectionVariables.get("noteTitle")} - Updated`
    );

    pm.expect(body.data.description).to.eql(
        "Updated by Postman automation"
    );

    pm.expect(body.data.category).to.eql("Home");
    pm.expect(body.data.completed).to.eql(true);
});

pm.test("Get Updated Note returns HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Updated Note state is persisted", function () {
    const body = pm.response.json();

    pm.expect(body.success).to.eql(true);

    pm.expect(body.data.id).to.eql(
        pm.collectionVariables.get("noteId")
    );

    pm.expect(body.data.title).to.eql(
        `${pm.collectionVariables.get("noteTitle")} - Updated`
    );

    pm.expect(body.data.description).to.eql(
        "Updated by Postman automation"
    );

    pm.expect(body.data.category).to.eql("Home");
    pm.expect(body.data.completed).to.eql(true);
});

pm.test("GET Note without token returns 401", function () {
    pm.response.to.have.status(401);
});

pm.test("API rejects missing authentication token", function () {
    const body = pm.response.json();

    pm.expect(body.message).to.eql(
        "No authentication token specified in x-auth-token header"
    );
});

pm.test("Delete Note returns HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Delete Note returns success response", function () {
    const body = pm.response.json();

    pm.expect(body.success).to.eql(true);
    pm.expect(body.message).to.eql(
        "Note successfully deleted"
    );
});

pm.test("Deleted Note returns HTTP 404", function () {
    pm.response.to.have.status(404);
});

pm.test("Deleted Note no longer exists", function () {
    const body = pm.response.json();

    pm.expect(body.success).to.eql(false);

    pm.expect(body.message).to.eql(
        "No note was found with the provided ID, Maybe it was deleted"
    );

    
